<?php $m = $args['model'] ?? array(); $statements = is_array($m['statements'] ?? null) ? $m['statements'] : array(); ?>
<section class="dzn-tp-section" aria-labelledby="teacher-finance"><h2 id="teacher-finance">پرداخت‌ها و صورت‌حساب‌ها</h2>
<?php if (($m['finance_state'] ?? 'unavailable') === 'available' && $statements) : ?><ul class="dzn-tp-rule-list"><?php foreach ($statements as $statement) : ?><li><strong><?php echo esc_html($statement['period_label'] ?? (($statement['period_start_utc']??'').' – '.($statement['period_end_utc']??''))); ?></strong> · <?php echo esc_html($statement['state'] ?? ''); ?> · <?php echo esc_html((string)($statement['payable_line_count'] ?? 0)); ?> ردیف قابل پرداخت · <?php echo esc_html((string)($statement['payable_amount_minor'] ?? '')); ?> <?php echo esc_html($statement['currency'] ?? ''); ?> (واحد خرد ارز)</li><?php endforeach; ?></ul>
<?php elseif (($m['finance_state'] ?? '') === 'empty') : ?><p>هنوز صورت‌حسابی برای نمایش ثبت نشده است.</p><?php else : ?><p>نمای مالی مدرس در حال حاضر در دسترس نیست. مبلغ یا وضعیت پرداختی از روی کلاس‌ها حدس زده نمی‌شود.</p><?php endif; ?></section>
